public class NumberUtils_isNumber_TriageGen1Test {





    @Test
    public void testIsNumber_Decimals() {
        assertTrue("Decimal", NumberUtils.isNumber("123.45"));
        assertTrue("Decimal with sign", NumberUtils.isNumber("-123.45"));
        assertTrue("Decimal starting with dot", NumberUtils.isNumber(".45")); // Note: logic depends on loop/foundDigit
        assertTrue("Decimal with zero", NumberUtils.isNumber("0.1"));
        assertFalse("Two decimal points", NumberUtils.isNumber("1.2.3"));
    }










}

