public class NumberUtils_isNumber_TriageGen1Test {







    @Test
    public void testIsNumber_Hexadecimal() {
        assertTrue("Simple hex", NumberUtils.isNumber("0x123"));
        assertTrue("Hex with negative sign", NumberUtils.isNumber("-0x1A"));
        assertTrue("Hex lowercase", NumberUtils.isNumber("0xabc"));
        assertTrue("Hex uppercase", NumberUtils.isNumber("0xABC"));
