        assertFalse("Hex incomplete", NumberUtils.isNumber("0x"));
        assertFalse("Hex invalid chars", NumberUtils.isNumber("0xG12"));
    }








}

package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {









    @Test
    public void testIsNumber_ScientificNotation() {
        assertTrue("Standard exponent", NumberUtils.isNumber("123E10"));
        assertTrue("Lowercase exponent", NumberUtils.isNumber("123e10"));
        assertTrue("Exponent with sign", NumberUtils.isNumber("123E+10"));
        assertTrue("Exponent with negative sign", NumberUtils.isNumber("123E-10"));
        assertTrue("Decimal with exponent", NumberUtils.isNumber("1.23E10"));
        assertFalse("No digit before E", NumberUtils.isNumber("E10"));
        assertFalse("Two E's", NumberUtils.isNumber("12E3E4"));
        assertFalse("Decimal in exponent", NumberUtils.isNumber("12E1.5"));
        assertFalse("Trailing E", NumberUtils.isNumber("123E"));
        assertFalse("Trailing sign in exponent", NumberUtils.isNumber("123E+"));
        assertFalse("Sign not allowed after digit without E", NumberUtils.isNumber("123-"));
    }






}

package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {











    @Test
    public void testIsNumber_TypeQualifiers() {
        // Testing d, D, f, F
        assertTrue("Integer D", NumberUtils.isNumber("123D"));
        assertTrue("Integer d", NumberUtils.isNumber("123d"));
        assertTrue("Float F", NumberUtils.isNumber("123.45F"));
        assertTrue("Float f", NumberUtils.isNumber("123.45f"));

        // Testing l, L
        assertTrue("Long L (no exponent)", NumberUtils.isNumber("123L"));
        assertTrue("Long l (no exponent)", NumberUtils.isNumber("123l"));
        assertFalse("Long L with exponent", NumberUtils.isNumber("123E10L"));
        assertFalse("Long l with exponent", NumberUtils.isNumber("123e10l"));

        // Invalid qualifiers
        assertFalse("Invalid qualifier", NumberUtils.isNumber("123X"));
        assertFalse("Invalid qualifier with sign", NumberUtils.isNumber("123-D"));
    }




}

package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {













    @Test
    public void testIsNumber_EdgeCases() {
        assertFalse("Just a dot", NumberUtils.isNumber("."));
        assertFalse("Just a sign", NumberUtils.isNumber("-"));
        assertFalse("Just a sign and dot", NumberUtils.isNumber("-."));

        // Testing the specific logic: (i < sz + 1 && allowSigns && !foundDigit)
        // This handles cases like "1E-" where the loop might attempt to process the sign
        assertFalse("Exponent sign without digit", NumberUtils.isNumber("1E-"));

        // Testing foundDigit requirement for qualifiers
        assertFalse("Qualifier without digit", NumberUtils.isNumber("D"));
    }


}

